 *
 * صورت و گزینه‌ها از دفترچه رسمی و پاسخنامه تشریحی همان دفترچه‌ها، و گزینه درست
 * برابر کلید رسمی سازمان سنجش (کلید اولیه ۳۰ تیر ۱۴۰۴، DEnasani1) است؛ کلید
