 * مطابق است). در دو سؤال، کلید رسمی با پاسخنامهٔ تشریحی متفاوت است و کلید رسمی
 * اعمال شده است: فلسفه ۱۳۶=۳ (تشریحی ۲) و فلسفه ۱۴۲=۲ (تشریحی ۳).
 *
 * ده سؤال به‌علت ایراد وارد نشده‌اند (دفترچه کامل ۱۶۰ سؤال دارد؛ در این فایل
