 *   گزینه‌ای درست ندارند؛ سؤال ۶ و ۱۲ خط پاسخ با حل تشریحی نمی‌خواند).
 * ـ ادبیات ۳۰ و ۳۲: «پاسخ گزینه (۱) طبق کلید سازمان سنجش — این سؤال ایراد دارد».
